    other=g.math('LESS_THAN',rank,sides-3.5)
    base=2.*g.math('CEIL',c.named(g,'st_cq_base','INT')*.5)
    records=c._store(g,records,'_cz_rank',rank,'INT');records=c._store(g,records,'_cz_base',base,'INT')
    total=c._stat(g,records,base*other,'Sum')
    long_count=g.math('MAXIMUM',total,c._read(g,records,'_cz_base',inner,'INT'))
    cap_count=g.math('MAXIMUM',8.,g.math('MAXIMUM',c._read(g,records,'_cz_base',cap_a,'INT'),c._read(g,records,'_cz_base',cap_b,'INT')))
    # Accumulate in cyclic opposite-chain order, then restore owner order.
    sort=g.node('GeometryNodeSortElements');sort.domain='POINT';g.bind(records,sort.inputs['Geometry']);g.bind(c.named(g,'_cz_rank','INT'),sort.inputs['Sort Weight'])
    ordered=sort.outputs['Geometry'];other=g.math('LESS_THAN',c.named(g,'_cz_rank','INT'),sides-3.5)
    acc=g.node('GeometryNodeAccumulateField');acc.domain='POINT';acc.data_type='FLOAT'
    g.bind(c.named(g,'st_cq_length')*other,acc.inputs['Value'])
    total_length=c.V(g,acc.outputs['Total']);start=c.V(g,acc.outputs['Trailing']);end=c.V(g,acc.outputs['Leading'])
    extra=(long_count-total)*.5
    count=c.named(g,'_cz_base','INT')+2.*(g.math('FLOOR',extra*end/g.math('MAXIMUM',total_length,1e-8)+1e-6)-g.math('FLOOR',extra*start/g.math('MAXIMUM',total_length,1e-8)+1e-6))
    owner=c.named(g,'st_cq_owner','INT');count=c.choose(g,other,count,c.choose(g,g.math('COMPARE',owner,inner),long_count,cap_count))
    ordered=c._store(g,ordered,'st_cq_count',count,'INT')
    acc=g.node('GeometryNodeAccumulateField');acc.domain='POINT';acc.data_type='INT'
    g.bind(c.named(g,'st_cq_count','INT')*other,acc.inputs['Value'])
    ordered=c._store(g,ordered,'st_cz_begin',acc.outputs['Trailing'],'INT')
    for key,value in (('inner',inner),('cap_a',cap_a),('cap_b',cap_b),('long',long_count),('across',cap_count)):
        ordered=c._store(g,ordered,'st_cz_'+key,value,'INT')
    sort=g.node('GeometryNodeSortElements');sort.domain='POINT';g.bind(ordered,sort.inputs['Geometry']);g.bind(owner,sort.inputs['Sort Weight'])
    records=sort.outputs['Geometry']
    short=g.math('MAXIMUM',c._read(g,records,'st_cq_length',cap_a),c._read(g,records,'st_cq_length',cap_b))
    valid=g.math('GREATER_THAN',sides,3.5)*g.math('LESS_THAN',short,.25*maximum)
    budget=(long_count+1.)*(cap_count+1.)+c._stat(g,records,(c.named(g,'st_cq_count','INT')+1.)*(radial+1.),'Sum')
    return records,budget,valid


