    m=c.V(g,inp.outputs['Fine Radial']);M=c.V(g,inp.outputs['Coarse Radial'])
    nu=c._read(g,fp,'st_cz_long',0,'INT');NU=c._read(g,cp,'st_cz_long',0,'INT')
    nv=c._read(g,fp,'st_cz_across',0,'INT');NV=c._read(g,cp,'st_cz_across',0,'INT')
    inner=c._read(g,cp,'st_cz_inner',0,'INT');a=c._read(g,cp,'st_cz_cap_a',0,'INT');bb=c._read(g,cp,'st_cz_cap_b',0,'INT')
    top=c._select(g,cp,g.math('LESS_THAN',c.named(g,'_cz_rank','INT'),sides-3.5))
    sort=g.node('GeometryNodeSortElements');sort.domain='POINT';g.bind(top,sort.inputs['Geometry']);g.bind(c.named(g,'st_cz_begin','INT'),sort.inputs['Sort Weight'])
    top=g.setpos(sort.outputs['Geometry'],g.xyz(c.named(g,'st_cz_begin','INT')))
